const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const clean = v => String(v ?? '').trim();

const source = input.body ? 'webhook' : 'manual';

return [{
  json: {
    campaign_id: clean(body.campaign_id) || `CAMPAIGN-${Date.now()}`,
    target_market: clean(body.target_market),
    target_industries: clean(body.target_industries),
    company_size_min: Number(body.company_size_min || 0),
    company_size_max: Number(body.company_size_max || 0),
    target_roles: clean(body.target_roles),
    problem_themes: clean(body.problem_themes),
    exclude_companies: clean(body.exclude_companies),
    max_accounts: Number(body.max_accounts || 10),
    minimum_account_score: Number(body.minimum_account_score || 65),
    minimum_contact_score: Number(body.minimum_contact_score || 60),
    request_source: source,
    requested_at: new Date().toISOString()
  }
}];

const j = $input.first().json || {};

const missing = [];
if (!j.target_market) missing.push('target_market');
if (!j.target_industries) missing.push('target_industries');
if (!j.target_roles) missing.push('target_roles');

return [{
  json: {
    ...j,
    criteria_valid: missing.length === 0,
    missing_fields: missing
  }
}];

const j = $input.first().json || {};
return [{
  json: {
    ...j,
    status: 'INVALID_CRITERIA',
    message: `Missing required fields: ${(j.missing_fields || []).join(', ')}`
  }
}];

