const source = $('Validate Criteria in Request').first().json;
const input = $input.first()?.json || {};

const candidates =
  input.companies ||
  input.results ||
  input.data ||
  (Array.isArray(input) ? input : []);

if (!Array.isArray(candidates)) {
  throw new Error('Company search response did not contain a company array.');
}

const exclusions = String(source.exclude_companies || '')
  .split(',')
  .map(v => v.trim().toLowerCase())
  .filter(Boolean);

return candidates.slice(0, source.max_accounts || 10).map((c, index) => ({
  json: {
    ...source,
    candidate_index: index + 1,
    company_name: String(c.name || c.company_name || '').trim(),
    company_domain: String(c.domain || c.website || c.company_domain || '').trim(),
    company_industry: String(c.industry || '').trim(),
    employee_count: Number(c.employee_count || c.employees || 0),
    company_location: String(c.location || c.country || '').trim(),
    company_description: String(c.description || c.summary || '').trim(),
    source_url: String(c.source_url || c.url || c.website || '').trim(),
    excluded_company: exclusions.includes(String(c.name || c.company_name || '').trim().toLowerCase())
  }
})).filter(x => x.json.company_name);

