const input = $input.item.json || {};
const raw =
  input.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ||
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  '';

if (!raw) throw new Error('No account research output returned.');

const parsed = JSON.parse(String(raw).replace(/```json/gi,'').replace(/```/g,'').trim());
const source = $('Normalise Company Website Evidence').item.json;

const fit = Number(parsed.account_fit || 0);
const relevance = Number(parsed.problem_relevance || 0);
const timing = Number(parsed.timing_signal || 0);
const confidence = Number(parsed.confidence || 0);

// Deterministic weighted score.
const accountScore = Math.round(
  fit * 0.40 +
  relevance * 0.30 +
  timing * 0.15 +
  confidence * 0.15
);

return {
  json: {
    ...source,
    fit_summary: parsed.fit_summary || '',
    relevant_problems: Array.isArray(parsed.relevant_problems) ? parsed.relevant_problems : [],
    research_evidence: Array.isArray(parsed.evidence) ? parsed.evidence : [],
    account_fit: fit,
    problem_relevance: relevance,
    timing_signal: timing,
    evidence_confidence: confidence,
    account_score: accountScore,
    reason_to_prioritise: parsed.reason_to_prioritise || ''
  }
};

const lookup = $input.item.json || {};
const source = $('Check Account Score Threshold').item.json;

return {
  json: {
    ...source,
    existing_account: Array.isArray(lookup.records) && lookup.records.length > 0,
    existing_account_record_id: lookup.records?.[0]?.id || ''
  }
};

// Runs once for all items: fans out each company's contacts, keeping the right account context.
const out = [];
$input.all().forEach((it, i) => {
  let account = {};
  try { account = $('Attach Existing Account Context').itemMatching(i).json || {}; } catch {}
  try {
    const created = $('Reattach New Account Context').itemMatching(i).json;
    if (created && created.company_name) account = created;
  } catch {}

  const input = it.json || {};
  const candidates = input.contacts || input.people || input.results || input.data || [];
  if (!Array.isArray(candidates)) {
    throw new Error('Contact discovery response did not contain a contact array.');
  }

  candidates.slice(0, 5).forEach((c, index) => {
    const name = String(c.name || c.full_name || '').trim();
    if (!name) return;
    out.push({
      json: {
        ...account,
        contact_index: index + 1,
        contact_name: name,
        contact_title: String(c.title || c.job_title || '').trim(),
        contact_email: String(c.email || '').trim(),
        contact_linkedin_url: String(c.linkedin_url || c.linkedin || '').trim(),
        contact_location: String(c.location || '').trim(),
        contact_source_url: String(c.source_url || c.linkedin_url || '').trim()
      },
      pairedItem: { item: i }
    });
  });
});
return out;

