const input = $input.item.json || {};
const raw =
  input.output?.[0]?.content?.find(c => c.type === 'output_text')?.text ||
  input.output?.[0]?.content?.[0]?.text ||
  input.text ||
  '';

if (!raw) throw new Error('No outreach brief returned.');

const parsed = JSON.parse(String(raw).replace(/```json/gi,'').replace(/```/g,'').trim());
const source = $('If Campaign Queue Item Is New').item.json;

return {
  json: {
    ...source,
    why_this_account: parsed.why_this_account || '',
    why_this_contact: parsed.why_this_contact || '',
    outreach_evidence_points: Array.isArray(parsed.evidence_points) ? parsed.evidence_points : [],
    suggested_opening: parsed.suggested_opening || '',
    do_not_claim: Array.isArray(parsed.do_not_claim) ? parsed.do_not_claim : [],
    review_status: 'Needs Human Review'
  }
};

// Runs once for all items: one summary covering every queued contact in this run.
const items = $input.all().map((it, i) => {
  let ctx = {};
  try { ctx = $('Analyze Outreach Brief').itemMatching(i).json || {}; } catch {}
  return { ...ctx, airtable_queue_record_id: it.json?.id || '' };
});
const first = items[0] || {};
const results = items.map(j => ({
  company_name: j.company_name,
  account_score: j.account_score,
  contact_name: j.contact_name,
  contact_title: j.contact_title,
  contact_score: j.contact_score,
  review_status: 'Needs Human Review',
  airtable_queue_record_id: j.airtable_queue_record_id
}));
return [{
  json: {
    campaign_id: first.campaign_id,
    request_source: first.request_source,
    queued_for_review: results.length,
    companies: [...new Set(results.map(r => r.company_name))],
    research_result: results
  }
}];

const data = $input.first().json || {};
const records = Array.isArray(data.records) ? data.records : [];

const now = Date.now();
const staleDays = Number($('Configure Queue Review Settings').first().json.stale_after_days || 3);

const rows = records.map(r => ({
  id: r.id,
  ...(r.fields || {})
}));

const stale = rows.filter(r => {
  const created = Date.parse(r.Created_At || '');
  if (!Number.isFinite(created)) return false;
  return (now - created) / 86400000 >= staleDays;
});

return [{
  json: {
    pending_count: rows.length,
    stale_count: stale.length,
    stale_items: stale.slice(0, 20),
    generated_at: new Date().toISOString(),
    summary: [
      `Pending outreach reviews: ${rows.length}`,
      `Stale reviews: ${stale.length}`,
      '',
      ...stale.slice(0,20).map(r =>
        `- ${r.Company_Name || ''} / ${r.Contact_Name || ''} — account ${r.Account_Score || ''}, contact ${r.Contact_Score || ''}`
      )
    ].join('\n')
  }
}];

const response = $input.item.json || {};
const company = $('Check Company Exclusion').item.json || {};
const maxChars = Number($('Configure Research Environment').first().json.company_site_max_chars || 12000);

// A failed fetch (continue-on-fail) returns an error object: treat it as no evidence.
const fetchFailed = Boolean(response.error);
let body = fetchFailed ? '' :
  response.body ??
  response.data ??
  response.html ??
  response;

if (typeof body !== 'string') {
  try { body = JSON.stringify(body); } catch { body = ''; }
}

const text = String(body || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, maxChars);

return {
  json: {
    ...company,
    company_site_evidence: text,
    company_site_evidence_available: !fetchFailed && text.length >= 100,
    company_site_fetch_error: fetchFailed ? String(response.error.message || 'fetch failed').slice(0, 200) : ''
  }
};

const source = $('Confirm New Account').item.json || {};
const created = $input.item.json || {};
return {
  json: {
    ...source,
    airtable_account_record_id: created.id || created.recordId || ''
  }
};

const source = $('Confirm New Contact').item.json || {};
const created = $input.item.json || {};
return {
  json: {
    ...source,
    airtable_contact_record_id: created.id || created.recordId || ''
  }
};

const lookup = $input.item.json || {};

let source = {};
try { source = $('Reattach New Contact Context').item.json || {}; } catch {}
if (!source.contact_name) {
  try { source = $('Attach Existing Contact Context').item.json || {}; } catch {}
}

return {
  json: {
    ...source,
    existing_campaign_queue_item: Array.isArray(lookup.records) && lookup.records.length > 0,
    existing_queue_record_id: lookup.records?.[0]?.id || ''
  }
};
